/* Beruf-Zugriff und Fortschritts-Brücke (wird von mkaufg.py an aufgaben.js angehängt; Quelle: quelle/gen/berufreg.js, nicht in lochmaster-web bearbeiten).
   BerufReg.cur()        gewählter Beruf (egs, ige, im, tpd, fll, ik, fi): ?beruf=… in der Adresse, sonst lm4.beruf, sonst egs
   BerufReg.labs(b)      Lab-Schlüssel dieses Berufs (ohne Hubs), Reihenfolge wie LAB_REG
   BerufReg.rows(b)      Aufgabenzeilen dieser Labs
   BerufReg.has(lab, b)  gehört das Lab zum Beruf?
   Brücke: Die eigenständigen Labs (Präfix tol, zer, …) speichern ihren Stand unter lm4.<präfix>.prog / .hints / .ctipps.
   Die Brücke spiegelt ihn nach lm4.tdone (Prozent, Maximum), sim.hints und lm4.ctipps (Stufe, Maximum), damit Lernpfad, Karriere, Abzeichen,
   Dashboard, Coach, Duell und der Stand-Export die Labs wie alle anderen sehen. Gespiegelt wird beim Laden und bei jedem Schreiben der drei Schlüssel. */
(function (root) {
  var ALL = ['egs', 'ige', 'im', 'tpd', 'fll', 'ik', 'fi'];
  var REG = root.LAB_REG || {}, ROWS = root.AUFGABEN || [];
  var ls = null; try { ls = root.localStorage; } catch (e) { ls = null; }
  function cur() {
    try { var q = /[?&]beruf=(\w+)/.exec(root.location.search); if (q && ALL.indexOf(q[1]) >= 0) return q[1]; } catch (e) {}
    try { var v = ls && ls.getItem('lm4.beruf'); if (v && ALL.indexOf(v) >= 0) return v; } catch (e) {}
    return 'egs';
  }
  function has(lab, b) { var r = REG[lab]; return !!r && !r.hub && (r.beruf || ['egs']).indexOf(b || cur()) >= 0; }
  function labs(b) { b = b || cur(); return Object.keys(REG).filter(function (k) { return has(k, b); }); }
  function rows(b) { var l = labs(b); return ROWS.filter(function (r) { return l.indexOf(r[1]) >= 0; }); }
  root.BerufReg = { ALL: ALL, cur: cur, has: has, labs: labs, rows: rows };

  if (!ls) return;
  var PF = Object.keys(REG).filter(function (k) { return REG[k].eig; });   // eigenständige Labs (Präfix = Schlüssel)
  var KEYRE = new RegExp('^lm4\\.(' + PF.join('|') + ')\\.(prog|hints|ctipps)$');
  function rd(k) { try { var v = JSON.parse(ls.getItem(k) || 'null'); return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; } catch (e) { return {}; } }
  function mergeMax(dst, src) { var ch = false; Object.keys(src).forEach(function (id) { var v = +src[id]; if (isFinite(v) && v > (+dst[id] || 0)) { dst[id] = v; ch = true; } }); return ch; }
  function sync() {
    var td = rd('lm4.tdone'), hi = rd('sim.hints'), ct = rd('lm4.ctipps'), c1 = false, c2 = false, c3 = false;
    PF.forEach(function (p) {
      if (mergeMax(td, rd('lm4.' + p + '.prog'))) c1 = true;
      if (mergeMax(hi, rd('lm4.' + p + '.hints'))) c2 = true;
      if (mergeMax(ct, rd('lm4.' + p + '.ctipps'))) c3 = true;
    });
    try { if (c1) ls.setItem('lm4.tdone', JSON.stringify(td)); if (c2) ls.setItem('sim.hints', JSON.stringify(hi)); if (c3) ls.setItem('lm4.ctipps', JSON.stringify(ct)); } catch (e) {}
  }
  root.BerufReg.sync = sync;
  try {
    var P = root.Storage && root.Storage.prototype, orig = P && P.setItem;
    if (orig && !orig.__bruecke) {
      var wrap = function (k, v) { var r = orig.apply(this, arguments); try { if (this === ls && KEYRE.test(String(k))) sync(); } catch (e) {} return r; };
      wrap.__bruecke = true; P.setItem = wrap;
    }
  } catch (e) {}
  sync();
})(typeof window !== 'undefined' ? window : globalThis);
